mapper.select:
SELECT base.id, base.unique_id as uniqueId, base.name, base.sex, base.phone, base.card_no as cardNo, base.account, base.email, base.flag, base.ext_attrs as extAttrs, case when base.status = '0' and busi.status = '0' and sbusi.status = '0' then '0' else '1' end as status, base.update_seria_num as updateSeriaNum, base.update_time as updateTime,
busi.update_seria_num as busiUpdateSeriaNum,
sbusi.update_seria_num as sbusiUpdateSeriaNum, sbusi.sub_treasury_id as subTreasuryId, sbusi.device_mgr as deviceMgr,
busi.face_mode as faceMode, busi.finger_mode as fingerMode, busi.iris_mode as irisMode, busi.fvein_mode as fveinMode, busi.face_iris_mode as faceIrisMode, busi.locked, dept.dept_code as deptCode, dept.dept_name as deptName FROM base_person_info base INNER JOIN channel_business busi ON busi.person_id = base.id AND busi.channel_id = #{channelId}
INNER JOIN ( SELECT person_id, string_agg(sub_treasury_id,',') AS sub_treasury_id, max( update_seria_num ) AS update_seria_num, min(status) as status, max(device_mgr) as device_mgr, min(channel_id) as channel_id FROM channel_subtreasury_busi WHERE channel_id = #{channelId} and sub_treasury_id IN
#{subId}
GROUP BY person_id ) sbusi ON sbusi.person_id = base.id AND sbusi.channel_id = busi.channel_id
LEFT JOIN sys_dept dept ON base.dept_id = dept.dept_id
or busi.update_seria_num > #{busiUpdateSeriaNum} or sbusi.update_seria_num > #{sbusiUpdateSeriaNum}
